export function createLanClient(onUpdate,onError){let session=null,stream=null,available=false,sending=false;
 const request=async(action,data={})=>{const res=await fetch('/api/'+action,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...data,token:session?.token})});const value=await res.json();if(!res.ok)throw new Error(value.error||'LAN request failed');return value;};
 const connect=async(action,data)=>{session=await request(action,data);stream?.close();stream=new EventSource('/api/events?token='+encodeURIComponent(session.token));stream.onmessage=e=>{try{onUpdate(JSON.parse(e.data),session);}catch(error){onError(error.message);}};stream.onerror=()=>onError('Connection interrupted. Keep the host server running.');return session;};
 return {get available(){return available;},get session(){return session;},async detect(){try{const r=await fetch('/api/info');available=r.ok&&(await r.json()).lan===true;}catch{available=false;}return available;},create:data=>connect('create',data),join:data=>connect('join',data),start:()=>request('start'),pause:paused=>request('pause',{paused}),async send(input){if(!session||sending)return;sending=true;try{await request('input',{input});}catch(e){onError(e.message);}finally{sending=false;}},async leave(){stream?.close();stream=null;if(session)try{await request('leave');}catch{}session=null;}};
}
